package main

import (
	"bytes"
	"fmt"
	"os/exec"
)

// QuerySLBAndExport queries SLB information using aliyun CLI and exports it to a file using jq.
// It runs the command: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > outputFile
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Build the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect aliyun's stdout to jq's stdin
	var stderr bytes.Buffer
	aliyunCmd.Stderr = &stderr

	// Get the pipe from aliyun to jq
	pipe, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun command: %w", err)
	}

	jqCmd.Stdin = pipe
	jqCmd.Stderr = &stderr

	// Start the aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Run the jq command and capture its output
	var jqOutput bytes.Buffer
	jqCmd.Stdout = &jqOutput

	if err := jqCmd.Start(); err != nil {
		aliyunCmd.Wait() // Clean up aliyun process
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for aliyun to finish
	if err := aliyunCmd.Wait(); err != nil {
		jqCmd.Wait() // Clean up jq process
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, stderr.String())
	}

	// Wait for jq to finish
	if err := jqCmd.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, stderr.String())
	}

	outputStr := jqOutput.String()

	// Write the output to the specified file
	if err := writeToFile(outputFile, outputStr); err != nil {
		return outputStr, fmt.Errorf("failed to write output to file: %w", err)
	}

	return outputStr, nil
}

// writeToFile writes the given content to the specified file path.
func writeToFile(filePath string, content string) error {
	cmd := exec.Command("sh", "-c", fmt.Sprintf("cat > %s", filePath))
	cmd.Stdin = bytes.NewBufferString(content)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to write to file: %w, stderr: %s", err, stderr.String())
	}
	return nil
}

func main() {
	// Example usage
	loadBalancerName := "my-slb"
	outputFile := "output.json"

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Query result:\n%s\n", result)
	fmt.Printf("Output written to: %s\n", outputFile)
}

