package main

import (
	"bytes"
	"fmt"
	"os/exec"
)

// QuerySLBAndExport queries SLB information using aliyun CLI and exports it to a file.
// It executes: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > outputFile
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// First command: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Second command: jq '.LoadBalancers.LoadBalancer[]'
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect stdout of aliyun to stdin of jq
	var jqOutput bytes.Buffer
	cmdJq.Stdout = &jqOutput
	cmdJq.Stderr = &bytes.Buffer{}

	// Get the pipe between commands
	pipe, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun command: %w", err)
	}
	cmdJq.Stdin = pipe

	// Start both commands
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}
	if err := cmdJq.Start(); err != nil {
		cmdAliyun.Wait()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for aliyun to finish and close the pipe
	if err := cmdAliyun.Wait(); err != nil {
		cmdJq.Wait()
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Close the pipe to signal EOF to jq
	pipe.Close()

	// Wait for jq to finish
	if err := cmdJq.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w", err)
	}

	result := jqOutput.String()

	// Write result to output file
	if err := writeToFile(outputFile, result); err != nil {
		return result, fmt.Errorf("failed to write to output file: %w", err)
	}

	return result, nil
}

// writeToFile writes content to the specified file path
func writeToFile(filePath string, content string) error {
	// Use shell redirection equivalent by writing directly to file
	// We'll use a simple approach: write the content to the file
	cmd := exec.Command("sh", "-c", fmt.Sprintf("cat > %s", filePath))
	cmd.Stdin = bytes.NewBufferString(content)
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("failed to write to file %s: %w, stderr: %s", filePath, err, stderr.String())
	}
	return nil
}

func main() {
	// Example usage
	loadBalancerName := "my-slb"
	outputFile := "output.json"

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Query completed successfully.\n")
	fmt.Printf("Result length: %d characters\n", len(result))
	fmt.Printf("Output written to: %s\n", outputFile)
}

