func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	return querySLBAndExportProperly(loadBalancerName, outputFile)
}

func querySLBAndExportProperly(loadBalancerName string, outputFile string) (string, error) {
	// Create the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Create the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect aliyun stdout to jq stdin
	pipe, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
	}
	jqCmd.Stdin = pipe

	// Capture jq output
	var jqOutput bytes.Buffer
	var jqError bytes.Buffer
	jqCmd.Stdout = &jqOutput
	jqCmd.Stderr = &jqError

	// Start aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start jq command
	if err := jqCmd.Start(); err != nil {
		aliyunCmd.Wait()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	aliyunErr := aliyunCmd.Wait()
	jqErr := jqCmd.Wait()

	if aliyunErr != nil {
		return "", fmt.Errorf("aliyun command failed: %w", aliyunErr)
	}

	if jqErr != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", jqErr, jqError.String())
	}

	result := jqOutput.String()

	// Write result to output file using a simple shell command
	writeCmd := exec.Command("sh", "-c", fmt.Sprintf("printf '%s' > %s", result, outputFile))
	var writeErr bytes.Buffer
	writeCmd.Stderr = &writeErr

	if err := writeCmd.Run(); err != nil {
		return "", fmt.Errorf("failed to write to output file: %w, stderr: %s", err, writeErr.String())
	}

	return result, nil
}

func main() {
