	// Strict input validation to prevent command injection
	// Only allow alphanumeric characters, hyphens, underscores, dots for loadBalancerName
	validName := regexp.MustCompile(`^[a-zA-Z0-9._-]+$`)
	if !validName.MatchString(loadBalancerName) || len(loadBalancerName) == 0 {
