	if !validFile.MatchString(outputFile) || len(outputFile) == 0 {
		return "", fmt.Errorf("invalid outputFile: contains disallowed characters")
	}

	// Check for path traversal attempts
	if strings.Contains(outputFile, "..") {
		return "", fmt.Errorf("invalid outputFile: path traversal detected")
	}

	// Construct the shell command safely by using proper quoting
	// Since we've validated inputs strictly, we can use them in the command
