// pipes the output through jq to format it, and writes the result to a file.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Step 1: Execute 'aliyun slb DescribeLoadBalancers --LoadBalancerName NAME'
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	var aliyunOut bytes.Buffer
	var aliyunErr bytes.Buffer
	aliyunCmd.Stdout = &aliyunOut
	aliyunCmd.Stderr = &aliyunErr

	err := aliyunCmd.Run()
	if err != nil {
		return "", fmt.Errorf("failed to execute aliyun command: %w, stderr: %s", err, aliyunErr.String())
	}

	// Step 2: Pipe the output through 'jq .LoadBalancers.LoadBalancer[]'
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	jqCmd.Stdin = &aliyunOut
	var jqOut bytes.Buffer
	var jqErr bytes.Buffer
	jqCmd.Stdout = &jqOut
	jqCmd.Stderr = &jqErr

	err = jqCmd.Run()
	if err != nil {
		return "", fmt.Errorf("failed to execute jq command: %w, stderr: %s", err, jqErr.String())
	}

	// Step 3: Write the formatted output to the specified file
	result := jqOut.String()

	// Use shell redirection equivalent by writing directly to the file
	writeCmd := exec.Command("sh", "-c", fmt.Sprintf("cat > %s", outputFile))
	writeCmd.Stdin = &jqOut
	var writeErr bytes.Buffer
	writeCmd.Stderr = &writeErr

	err = writeCmd.Run()
	if err != nil {
		return "", fmt.Errorf("failed to write output to file: %w, stderr: %s", err, writeErr.String())
	}

	return result, nil
}

func main() {
	// Example usage
	loadBalancerName := "my-slb-instance"
	outputFile := "output.json"

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Successfully exported SLB information to %s\n", outputFile)
	fmt.Printf("Result:\n%s\n", result)
}

