	var stderrBuf bytes.Buffer
	cmdAliyun.Stderr = &stderrBuf
	cmdJq.Stderr = &stderrBuf

	// Create pipe between aliyun and jq
	pipeReader, pipeWriter, err := os.Pipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}

	cmdAliyun.Stdout = pipeWriter
	cmdJq.Stdin = pipeReader

