// QuerySLBAndExport executes the aliyun slb DescribeLoadBalancers command,
// pipes the output through jq to filter LoadBalancer entries,
// and writes the result to the specified output file.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Build the jq command
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect stdout of aliyun to stdin of jq
	aliyunStdout, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun command: %w", err)
	}

	jqCmd.Stdin = aliyunStdout

	// Capture jq's stdout
	var jqOutput bytes.Buffer
	jqCmd.Stdout = &jqOutput

	// Start both commands
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	if err := jqCmd.Start(); err != nil {
		aliunCmdWaitErr := aliyunCmd.Wait()
		return "", fmt.Errorf("failed to start jq command: %w, aliyun wait error: %v", err, aliunCmdWaitErr)
	}

	// Wait for aliyun to complete
	if err := aliyunCmd.Wait(); err != nil {
		// Still try to get jq output even if aliyun failed
		jqWaitErr := jqCmd.Wait()
		outputStr := jqOutput.String()
		return outputStr, fmt.Errorf("aliyun command failed: %w, jq wait error: %v", err, jqWaitErr)
	}

	// Wait for jq to complete
	if err := jqCmd.Wait(); err != nil {
		outputStr := jqOutput.String()
		return outputStr, fmt.Errorf("jq command failed: %w", err)
	}

	// Get the filtered JSON output
	outputStr := jqOutput.String()

	// Write the output to the specified file
	if err := writeFile(outputFile, []byte(outputStr)); err != nil {
		return outputStr, fmt.Errorf("failed to write output to file %s: %w", outputFile, err)
	}

	return outputStr, nil
}

// writeFile writes data to a file with standard permissions
func writeFile(filename string, data []byte) error {
	return exec.Command("sh", "-c", fmt.Sprintf("cat > %s", filename)).Run()
}

func main() {
	// Example usage
	loadBalancerName := "my-load-balancer"
	outputFile := "output.json"

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Printf("Successfully exported SLB info to %s\n", outputFile)
	fmt.Printf("Output:\n%s\n", result)
}

