// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate loadBalancerName: only allow alphanumeric, hyphens, underscores, dots
	validName := regexp.MustCompile(`^[a-zA-Z0-9._-]+$`)
	if !validName.MatchString(loadBalancerName) {
		return "", fmt.Errorf("invalid characters in loadBalancerName")
	}

	// Validate outputFile: only allow alphanumeric, hyphens, underscores, dots, slashes
	validFile := regexp.MustCompile(`^[a-zA-Z0-9._/-]+$`)
	if !validFile.MatchString(outputFile) {
		return "", fmt.Errorf("invalid characters in outputFile")
	}

	// Construct commands without using shell interpretation
	// Step 1: Run aliyun slb DescribeLoadBalancers
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Capture the output from aliyun command
	aliyunOutput, err := aliyunCmd.Output()
	if err != nil {
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Step 2: Pipe output through jq
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	jqCmd.Stdin = strings.NewReader(string(aliyunOutput))

	jqOutput, err := jqCmd.Output()
	if err != nil {
		return "", fmt.Errorf("jq command failed: %w", err)
	}

	// Step 3: Write output to file
	err = os.WriteFile(outputFile, jqOutput, 0644)
	if err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	return string(jqOutput), nil
}

