// It executes the command: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME | jq '.LoadBalancers.LoadBalancer[]' > output.json
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// Create the first command: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Create the second command: jq '.LoadBalancers.LoadBalancer[]'
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect stdout of cmd1 to stdin of cmd2
	cmd2.Stdin, _ = cmd1.StdoutPipe()
	var stderrBuf bytes.Buffer
	cmd2.Stderr = &stderrBuf

	// Start both commands
	err := cmd1.Start()
	if err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	err = cmd2.Start()
	if err != nil {
		cmd1.Wait() // Clean up cmd1 if cmd2 fails to start
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for cmd1 to complete
	err = cmd1.Wait()
	if err != nil {
		cmd2.Wait() // Clean up cmd2
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// Capture the output from cmd2
	var outputBuf bytes.Buffer
	cmd2.Stdout = &outputBuf

	// Wait for cmd2 to complete
	err = cmd2.Wait()
	if err != nil {
		stderrOutput := stderrBuf.String()
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, stderrOutput)
	}

	outputStr := outputBuf.String()

	// Write the output to the specified file
	writeCmd := exec.Command("sh", "-c", fmt.Sprintf("cat > %s", outputFile))
	writeCmd.Stdin = &outputBuf
	var writeStderr bytes.Buffer
	writeCmd.Stderr = &writeStderr

	err = writeCmd.Run()
	if err != nil {
		return outputStr, fmt.Errorf("failed to write to output file: %w, stderr: %s", err, writeStderr.String())
	}

	return outputStr, nil
}

func main() {
	// Example usage
	result, err := QuerySLBAndExport("my-slb", "output.json")
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Result:\n%s\n", result)
}

