package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// QuerySLBAndExport queries SLB information using aliyun CLI and exports it to a file using jq.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" {
		return "", fmt.Errorf("loadBalancerName cannot be empty")
	}
	if outputFile == "" {
		return "", fmt.Errorf("outputFile cannot be empty")
	}

	// Build the aliyun command
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Execute the aliyun command and capture its output
	var stdout, stderr bytes.Buffer
	aliyunCmd.Stdout = &stdout
	aliyunCmd.Stderr = &stderr

	err := aliyunCmd.Run()
	if err != nil {
		return "", fmt.Errorf("failed to execute aliyun command: %w, stderr: %s", err, stderr.String())
	}

	// Check if there's any output
	output := stdout.Bytes()
	if len(output) == 0 {
		return "", fmt.Errorf("aliyun command returned no output")
	}

	// Build the jq command to format the output
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	jqCmd.Stdin = bytes.NewReader(output)
	var jqStdout, jqStderr bytes.Buffer
	jqCmd.Stdout = &jqStdout
	jqCmd.Stderr = &jqStderr

	err = jqCmd.Run()
	if err != nil {
		return "", fmt.Errorf("failed to execute jq command: %w, stderr: %s", err, jqStderr.String())
	}

	// Write the formatted output to the specified file
	formattedOutput := jqStdout.Bytes()
	err = os.WriteFile(outputFile, formattedOutput, 0644)
	if err != nil {
		return "", fmt.Errorf("failed to write output to file %s: %w", outputFile, err)
	}

	// Return the formatted output as string
	result := strings.TrimSpace(string(formattedOutput))
	return result, nil
}

func main() {
	// Example usage
	loadBalancerName := "my-slb"
	outputFile := "output.json"

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Successfully exported SLB info to %s\n", outputFile)
	if result != "" {
		fmt.Println("Result preview:")
		fmt.Println(result)
	}
}

