package main

import (
	"bytes"
	"fmt"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI to describe load balancers and exports the result to a file.
// It uses a pipeline: aliyun slb DescribeLoadBalancers | jq '.LoadBalancers.LoadBalancer[]' > outputFile
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Build the first command: aliyun slb DescribeLoadBalancers --LoadBalancerName NAME
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Build the second command: jq '.LoadBalancers.LoadBalancer[]'
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Connect the stdout of aliyun to the stdin of jq
	cmdJq.Stdin, _ = cmdAliyun.StdoutPipe()

	// Capture the output of jq
	var outBuf bytes.Buffer
	cmdJq.Stdout = &outBuf

	// Start the jq command
	if err := cmdJq.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Run the aliyun command
	if err := cmdAliyun.Run(); err != nil {
		// Close the pipe to ensure jq exits
		cmdJq.Wait()
		return "", fmt.Errorf("failed to run aliyun command: %w", err)
	}

	// Wait for jq to finish processing
	if err := cmdJq.Wait(); err != nil {
		return "", fmt.Errorf("failed to wait for jq command: %w", err)
	}

	output := outBuf.String()

	// Write the output to the specified file
	if err := writeFile(outputFile, []byte(output)); err != nil {
		return output, fmt.Errorf("failed to write output to file: %w", err)
	}

	return output, nil
}

// writeFile writes data to a file with standard permissions
func writeFile(filename string, data []byte) error {
	return exec.Command("sh", "-c", fmt.Sprintf("cat > %s", filename)).Run()
}

func main() {
	// Example usage
	loadBalancerName := "my-slb"
	outputFile := "output.json"

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}
	fmt.Printf("Result:\n%s\n", result)
}

